	input sys_rst_n_i;
	input cordic_req;
	input [31:0] W;
	output cordic_ack;
	output [31:0] theta;

	wire sys_clk_i;
	wire sys_rst_n_i;
	wire cordic_req;
	wire [31:0] W;
	wire cordic_ack;
	wire [31:0] theta;
	wire [15:0] cordic_arctanh1_amplitude;
