		.X(W_L),
		.Y(cordic_arctanh1_amplitude),
		.cordic_ack(cordic_ack),
		.amplitude( ),
		.theta(theta),
		.sys_clk_i(sys_clk_i),
		.sys_rst_n_i(sys_rst_n_i));

endmodule    //cordic_arccos

